import ast

# Parse history.py to get all method names
with open('nanobot/core/history.py') as f:
    tree = ast.parse(f.read())

methods = set()
for node in ast.walk(tree):
    if isinstance(node, ast.ClassDef) and node.name == 'History':
        for n in node.body:
            if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef)):
                methods.add(n.name)

# Now search all other .py files for usage of these methods
import os, re

usage = {m: [] for m in methods}
for root, dirs, files in os.walk('nanobot'):
    if '__pycache__' in root: continue
    for fname in files:
        if not fname.endswith('.py'): continue
        if fname == 'history.py': continue
        fpath = os.path.join(root, fname)
        with open(fpath) as f:
            content = f.read()
        for m in methods:
            if f'.{m}(' in content or f'.{m}\\n' in content:
                usage[m].append(fpath)

for root, dirs, files in os.walk('tests'):
    for fname in files:
        if not fname.endswith('.py'): continue
        fpath = os.path.join(root, fname)
        with open(fpath) as f:
            content = f.read()
        for m in methods:
            if f'.{m}(' in content or f'.{m}\\n' in content:
                usage[m].append(fpath)

unused = [m for m in methods if len(usage[m]) == 0]
print(f'Total History methods: {len(methods)}')
print(f'Unused outside history.py: {len(unused)}')
for m in sorted(unused):
    print(f'  {m}')
print()
print('Used methods (with locations):')
for m in sorted(methods):
    if usage[m]:
        print(f'  {m}: {usage[m]}')
" 2>&1
